  'Creator publishing' => 'ፈጣሪ ማተም',
  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'የፈጣሪ ስቱዲዮ ይዘት አስተዳደር ተመሳሳዩን የታይነት ሞዴል ይጠቀማል፡ ይፋዊ፣ ያልተዘረዘረ ወይም የግል። የታቀዱ ቪዲዮዎች ከተለቀቁ በኋላ የተጠየቀውን ታይነት ይጠቀማሉ።',
