  'Current upload categories' => 'የአሁኑ ሰቀላ ምድቦች',
  'Data is used to authenticate users, publish and process content, show videos and channels, personalize account preferences, prevent abuse, support moderation, provide admin analytics, and keep creator and viewer features working.' => 'ውሂብ ተጠቃሚዎችን ለማረጋገጥ፣ ይዘቶችን ለማተም እና ለማስኬድ፣ ቪዲዮዎችን እና ቻናሎችን ለማሳየት፣ የመለያ ምርጫዎችን ለግል ለማበጀት፣ አላግባብ መጠቀምን ለመከላከል፣ መስተካከልን ለመደገፍ፣ የአስተዳዳሪ ትንታኔዎችን ለማቅረብ እና የፈጣሪ እና የተመልካች ባህሪያት እንዲሰሩ ለማድረግ ይጠቅማል።',
