  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'ምንም የሚከፈልበት ግብይት በተገናኘው የሂሳብ አከፋፈል አቅራቢ ወይም የመድረክ መዝገቦች ውስጥ ከሌለ፣ ገንዘብ ለመመለስ ምንም የመሣሪያ ስርዓት ክፍያ የለም። ተመላሽ ገንዘቦች በእውነተኛ የክፍያ መዝገቦች፣ የደንበኝነት ምዝገባ መታወቂያዎች፣ ደረሰኞች ወይም የግብይት ማጣቀሻዎች ላይ ብቻ መገምገም ይችላሉ።',
