  'Other' => 'ሌላ',
  'Partnerships, press, and platform operations.' => 'ሽርክና፣ ፕሬስ እና የመድረክ ስራዎች።',
  'Payment help' => 'የክፍያ እገዛ',
  'Platform' => 'መድረክ',
  'Playback' => 'መልሶ ማጫወት',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'የመልሶ ማጫወት ሂደት፣ የቆይታ ሁኔታ፣ መውደዶች፣ አስተያየቶች፣ ምዝገባዎች፣ ማሳወቂያዎች እና የአስተዳዳሪ ትንታኔዎች ከተረጋገጡ የመሣሪያ ስርዓት ባህሪያት ጋር ሲገናኙ በመረጃ ቋቱ ውስጥ ይቀመጣሉ።',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'መልሶ ማጫወት፣ አስተያየቶች፣ መውደዶች፣ በኋላ ይመልከቱ፣ የደንበኝነት ምዝገባዎች፣ ማሳወቂያዎች፣ መልዕክቶች፣ አጫዋች ዝርዝሮች እና የቋንቋ ቅንብሮች በዋናው የአሰሳ እና የመለያ ሜኑ በኩል ይገኛሉ።',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub የፈጣሪን ይዘት ከአንድ መለያ ለመስቀል፣ ለመመልከት፣ መርሐግብር ለማውጣት፣ ለማስተዳደር እና ለማስተካከል የቪዲዮ መድረክ ነው።',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub ለፈጣሪዎች፣ ተመልካቾች፣ ማህበረሰቦች እና የመድረክ ኦፕሬተሮች የተገነባው በዚህ ስምሪት ላይ የሚሰራ የቪዲዮ መድረክ ነው።',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub የፈጣሪ ቻናሎችን፣ የቪዲዮ ሰቀላዎችን፣ የታቀዱ ህትመቶችን፣ ምዝገባዎችን፣ አስተያየቶችን፣ አጫዋች ዝርዝሮችን፣ በኋላ ይመልከቱ፣ የቀጥታ የይዘት ገፆችን እና የአስተዳደር መሳሪያዎችን ከአንድ መድረክ ያቀርባል።',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ለመግቢያ ክፍለ-ጊዜዎች፣ የኤፒአይ ማረጋገጫ፣ CSRF/የደህንነት ባህሪ፣ የቋንቋ ምርጫ፣ የገጽታ ምርጫ፣ የመለያ ምናሌ ሁኔታ እና ሌሎች አፕሊኬሽኑ እንዲሰራ የሚያስፈልጉትን አስፈላጊ ኩኪዎች እና የአሳሽ ማከማቻ ይጠቀማል።',
  'playhub_language, theme' => 'playhub_ቋንቋ፣ ጭብጥ',
  'Popular questions' => 'ታዋቂ ጥያቄዎች',
