  'Send a message and it will be saved for admins.' => 'መልእክት ይላኩ እና ለአስተዳዳሪዎች ይቀመጣል።',
  'Send billing details to admin support for review.' => 'የክፍያ ዝርዝሮችን ለግምገማ ለአስተዳዳሪ ድጋፍ ይላኩ።',
