  'Still can’t find an answer?' => 'አሁንም መልስ ማግኘት አልቻልኩም?',
  'Stored for admins' => 'ለአስተዳዳሪዎች የተከማቸ',
  'Stores language, theme, and interface preferences.' => 'ቋንቋ፣ ገጽታ እና የበይነገጽ ምርጫዎችን ያከማቻል።',
  'Studio, playlists, analytics, channels.' => 'ስቱዲዮ፣ አጫዋች ዝርዝሮች፣ ትንታኔዎች፣ ሰርጦች።',
  'Submit a billing or refund message to admin support.' => 'ለአስተዳዳሪ ድጋፍ የክፍያ መጠየቂያ ወይም የተመላሽ ገንዘብ መልእክት ያስገቡ።',
  'Submit refund request' => 'የተመላሽ ገንዘብ ጥያቄ ያስገቡ',
  'Submit request' => 'ጥያቄ አስገባ',
  'Subscription cancellation' => 'የደንበኝነት ምዝገባ መሰረዝ',
  'Support dashboard' => 'ዳሽቦርድን ይደግፉ',
  'System status' => 'የስርዓት ሁኔታ',
  'Table' => 'ጠረጴዛ',
  'Taxonomies' => 'ታክሶኖሚዎች',
  'Technical issue' => 'የቴክኒክ ጉዳይ',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'ከአሁኑ የPlayHub API ጋር ለመዋሃድ ቴክኒካዊ ማስታወሻዎች እና የስራ ፍሰት ይስቀሉ።',
  'Tell us more about your question or request...' => 'ስለጥያቄዎ ወይም ጥያቄዎ የበለጠ ይንገሩን።',
  'Terms of Use' => 'የአጠቃቀም ውል',
  'The configured' => 'የተዋቀረው',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'የገንቢው ገጽ ከቀጥታ የላራቬል ደጋፊ ጋር ተያይዟል፡ የመንገድ ክምችት፣ የውሂብ ጎታ ብዛት፣ የሰቀላ ገደቦች እና የመሳሪያ ስርዓት ሜታዳታ ከ/api/ገንቢዎች ተጭነዋል።',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'የፊት ለፊቱ እንደ የተመረጠ ቋንቋ፣ ጭብጥ፣ የመልሶ ማጫወት ወረፋ፣ የምልከታ ሂደት እና የበይነገጽ ሁኔታ ያሉ ምርጫዎችን ያከማቻል ስለዚህ ልምዱ በገጽ አሰሳ እና ዳግም መጫን ላይ ወጥነት ይኖረዋል።',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'የማቀነባበሪያው ስራ አተረጓጎም ያስቀምጣል፣ ሲያስፈልግ ጥፍር አከሎችን ይፈጥራል፣ መግለጫ ጽሑፎችን ያከማቻል እና ሂደቱ ሲጠናቀቅ ዝግጁ የሆኑ ቪዲዮዎችን ምልክት ያደርጋል። መርሐግብር አውጪው እስኪለቅቃቸው ድረስ ወደፊት የታቀዱ ቪዲዮዎች ግላዊ ሆነው ይቆያሉ።',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'የሰቀላ ስርዓቱ በመረጃ ቋት የተደገፈ፣ ከኤፒአይ ምድቦችን እና ቋንቋዎችን ይደግፋል፣ የተሰቀሉ ቪዲዮዎችን ያዘጋጃል፣ ጥፍር አከሎችን እና መግለጫ ጽሑፎችን ያከማቻል እና የታቀዱ ይዘቶችን እስከሚወጣበት ጊዜ ድረስ ሚስጥራዊ ያደርገዋል።',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'ይህ ገጽ PlayHub እንዴት ኩኪዎችን እና የአሳሽ ማከማቻን ለክፍለ-ጊዜዎች፣ ደህንነት፣ ምርጫዎች፣ መልሶ ማጫወት እና የተረጋገጡ ባህሪያት እንደሚጠቀም ያብራራል።',
  'Ticket source' => 'የቲኬት ምንጭ',
  'Top content categories' => 'ከፍተኛ የይዘት ምድቦች',
  'Topic' => 'ርዕስ',
  'Transaction / invoice' => 'ግብይት / ደረሰኝ',
  'Transaction / invoice ID' => 'የግብይት / የክፍያ መጠየቂያ መታወቂያ',
  'Unable to send message.' => 'መልእክት መላክ አልተቻለም።',
  'Unable to submit refund request.' => 'የተመላሽ ገንዘብ ጥያቄ ማስገባት አልተቻለም።',
  'Understanding admin support tickets' => 'የአስተዳዳሪ ድጋፍ ትኬቶችን መረዳት',
  'Upload and processing help' => 'ስቀል እና ማቀናበር እገዛ',
  'Upload chunks' => 'ቁርጥራጮችን ይስቀሉ',
  'Upload issues' => 'የመጫን ጉዳዮች',
  'Upload languages' => 'ቋንቋዎችን ስቀል',
  'Upload limit' => 'የሰቀላ ገደብ',
  'Upload options' => 'የመስቀል አማራጮች',
  'Upload or processing' => 'ስቀል ወይም ማቀናበር',
  'Upload page' => 'የመስቀል ገጽ',
  'Upload pipeline' => 'የቧንቧ መስመር ይጫኑ',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'በቀጥታ የPlayHub ውሂብ ይስቀሉ፣ ይመልከቱ፣ ይመዝገቡ፣ ያስተካክሉ እና ይገንቡ።',
  'Uploaded videos' => 'የተጫኑ ቪዲዮዎች',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'የተጫኑ ቪዲዮዎች ወደ ሊጫወቱ በሚችሉ ትርጉሞች ውስጥ ተቀምጠዋል። የማስኬጃ ጊዜ በፋይል መጠን፣ ቆይታ፣ የአገልጋይ ጭነት እና የወረፋ ሁኔታ ይወሰናል። የሰቀላ ገጹ እና የፈጣሪ ስቱዲዮ ከቪዲዮ ቀረጻው እውነተኛ ሂደት ሁኔታን ያሳያሉ።',
  'Uploads, scheduling, and processing are available.' => 'ሰቀላዎች፣ መርሐግብር ማስያዝ እና ማቀናበር ይገኛሉ።',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'ለፈጣሪ የስራ ፍሰቶች /ኤፒ/ቪዲዮዎች፣ የሰርጥ የመጨረሻ ነጥቦችን እና የተረጋገጡ መንገዶችን ይጠቀሙ።',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'አስተዳዳሪዎች ትክክለኛውን የይዘት ማጣቀሻ እንዲቀበሉ አብሮ የተሰራ የሪፖርት እርምጃዎችን ለቪዲዮዎች እና አስተያየቶች ይጠቀሙ። የአስተዳዳሪ ዳሽቦርድ ገጾች ለተጠቃሚዎች፣ ይዘቶች፣ ሪፖርቶች፣ ገቢ መፍጠር፣ ትንታኔዎች፣ ድጋፍ፣ ሚናዎች እና የስርዓት ቅንብሮች የቀጥታ የውሂብ ጎታ ውሂብን ይጠቀማሉ።',
  'Use Contact Us' => 'እኛን ያነጋግሩን ይጠቀሙ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'JSON ለመደበኛ የኤፒአይ ጥያቄዎች እና ለፋይል ሰቀላ FormData ይጠቀሙ። ማረጋገጫን አያልፉ፡ ምድቦች እና ቋንቋዎች የውሂብ ጎታ መታወቂያዎች ናቸው፣ ታይነት ይፋዊ፣ ያልተዘረዘረ ወይም የግል ብቻ ነው፣ እና መግለጫ ጽሑፎች SRT፣ VTT ወይም TXT ፋይሎችን ይቀበላሉ።',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'የእርስዎን መገለጫ፣ ደህንነት፣ የይለፍ ቃል፣ ባለሁለት ደረጃ ማቅረቢያ፣ መሣሪያዎች፣ ምርጫዎች እና የማሳወቂያ አማራጮችን ለማዘመን ቅንብሮችን ይጠቀሙ። መለያዎን መድረስ ካልቻሉ የመግቢያ ፍሰቱን ይጠቀሙ እና የመለያውን ኢሜል ለጣቢያው አስተዳዳሪ ያቅርቡ።',
  'Use the contact form' => 'የእውቂያ ቅጹን ይጠቀሙ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'አስተዳዳሪዎች ትክክለኛውን የይዘት ማጣቀሻ እንዲቀበሉ የሪፖርት እርምጃዎችን በቪዲዮዎች፣ አስተያየቶች እና የማህበረሰብ ልጥፎች ላይ ይጠቀሙ።',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'ይዘቱ የመሣሪያ ስርዓት ህጎችን ሊጥስ በሚችልበት ጊዜ በቪዲዮዎች፣ አስተያየቶች እና የማህበረሰብ ልጥፎች ላይ የሪፖርት እርምጃዎችን ይጠቀሙ። እነዚህ ሪፖርቶች ከእውነተኛው የይዘት መዝገብ ጋር የተሳሰሩ እና ከአጠቃላዩ መልእክት የተሻሉ ናቸው ምክንያቱም አስተዳዳሪዎች ትክክለኛውን እቃ መገምገም ይችላሉ።',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'ለመለያ እገዛ፣ የይዘት ሪፖርቶች፣ ቴክኒካዊ ጉዳዮች እና የአስተዳዳሪ ጥያቄዎች ትክክለኛውን የPlayHub ቻናል ይጠቀሙ።',
  'Video categories' => 'የቪዲዮ ምድቦች',
  'Video for everyone. Built for creators and viewers.' => 'ቪዲዮ ለሁሉም። ከእውነተኛ የመሳሪያ ስርዓት ውሂብ የተሰራ።',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'የቪዲዮ ሰቀላ፣ መርሐግብር፣ ድንክዬዎች እና የማስኬጃ ችግሮች።',
  'Videos, thumbnails, captions, processing.' => 'ቪዲዮዎች፣ ድንክዬዎች፣ መግለጫ ጽሑፎች፣ ሂደት።',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ተመልካቾች ምድቦችን ማሰስ፣ ቪዲዮዎችን መፈለግ፣ ይዘትን መመልከት፣ ለሰርጦች መመዝገብ፣ ቪዲዮዎችን በኋላ ለማየት ማስቀመጥ፣ አስተያየት መስጠት፣ ማሳወቂያዎችን መቀበል እና የቋንቋ እና የተደራሽነት ምርጫዎችን ማስተዳደር ይችላሉ።',
  'Viewing and community help' => 'እይታ እና የማህበረሰብ እገዛ',
  'Waiting for backend endpoint inventory.' => 'የኋላ መጨረሻ ነጥብ ክምችት በመጠበቅ ላይ።',
  'We’re here to help.' => 'እኛ ለመርዳት እዚህ ነን።',
  'What is PlayHub?' => 'PlayHub ምንድን ነው?',
  'What PlayHub does' => 'PlayHub የሚያደርገው',
  'Where do contact messages go?' => 'የእውቂያ መልእክቶች የት ይሄዳሉ?',
  'Why is my video still processing?' => 'ለምንድነው የእኔ ቪዲዮ አሁንም እየተሰራ ያለው?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'አዎ። በተሰቀለው ገጽ ላይ የቤተኛ የጊዜ ሰሌዳ ቀን እና የሰዓት መስኩን ይጠቀሙ። የኋለኛው ክፍል መርሐግብር የተያዘለት_በትን ያከማቻል፣ ቪዲዮውን ያስኬዳል፣ ቀኑ ወደፊት ሲሆን ሚስጥራዊ ያደርገዋል፣ እና የላራቭል መርሐግብር አውጪ ከተያዘለት ጊዜ በኋላ ሲሮጥ ይለቀዋል።',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'አዎ። ሰቀላ ላይ የቤተኛ መርሐግብር መስኩን ተጠቀም። የኋለኛው ክፍል መርሐግብር የተያዘለትን_ at ያከማቻል እና የመርሃግብር ሰዓቱ ሲደርስ ቪዲዮውን ከተሰራ በኋላ ይለቃል።',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'እንደ እንግዳ እያሰሱ ነው። መለያ-ተኮር መሳሪያዎችን ለመድረስ ይግቡ።',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'ለመለያዎ ምስክርነቶች፣ የመገለጫ እንቅስቃሴ፣ ለተሰቀሉ ይዘቶች፣ አስተያየቶች፣ መልዕክቶች እና ከማንኛዉም ከመለያዎ ለሚደረጉ የፈጣሪ ወይም የአስተዳዳሪ እርምጃዎች ኃላፊነቱን ይወስዳሉ። ጠንካራ የይለፍ ቃላትን ተጠቀም እና ባለ ሁለት ደረጃ የማድረስ ዘዴዎችን ወቅታዊ አድርግ።',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'በአሳሽዎ ቅንብሮች ውስጥ የአሳሽ ኩኪዎችን እና የአካባቢ ማከማቻን ማጽዳት ይችላሉ። አስፈላጊ ማከማቻን ማጽዳት ዘግቶ ሊያስወጣዎት፣ የቋንቋ/ገጽታ ምርጫዎችን ዳግም ሊያስጀምር፣ የአካባቢ መልሶ ማጫወት ሁኔታን ሊያስወግድ እና እንደገና እንዲገቡ ሊጠይቅዎት ይችላል።',
  'You receive a response by email.' => 'በኢሜል ምላሽ ያገኛሉ።',
  'You’re in control' => 'እርስዎ ነዎት የሚቆጣጠሩት።',
  'Your choices' => 'የእርስዎ ምርጫዎች',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'መልእክትህ በቀጥታ በድህረ ገጹ ጀርባ ላይ ተቀምጦ በአስተዳዳሪ ዳሽቦርድ በድጋፍ ስር ይታያል።',
