  'Improve public reach' => 'የህዝብ ተደራሽነትን አሻሽል',
  'Keep strong videos visible and refresh weak titles.' => 'ጠንካራ ቪዲዮዎች እንዲታዩ ያቆዩ እና ደካማ ርዕሶችን ያድሱ።',
