  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'የVimeo ዝርዝሮችን ያመጣል እና ከVimeo የተከተተ ተጫዋች ጋር ይጫወታል።',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'የDailymotion ዝርዝሮችን ያፈልቃል እና በDailymotion መክተት ማጫወቻ ይጫወታል።',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'የነቃ አገልግሎት ይምረጡ እና ይፋዊ የቪዲዮ URL ለጥፍ። PlayHub ዝርዝሮቹን አምጥቶ ከመጀመሪያው አቅራቢ ያጫውታል።',
